-- Isolated database only; synthetic identities, authoritative role helpers, rollback.
BEGIN;
DO $$ DECLARE v uuid; v2 uuid; v3 uuid; mid uuid; f uuid; h text:=repeat('a',64); actor uuid; n integer; path text; BEGIN
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 SET LOCAL ROLE authenticated;
 v:=public.board_minutes_save_revision(NULL,NULL,'topical','synthetic-original','2026-11-06','Synthetic board minutes','Private report','["Decision"]','["Action"]','https://example.invalid/source',true,h);
 IF v IS DISTINCT FROM public.board_minutes_save_revision(NULL,NULL,'topical','synthetic-original','2026-11-06','Synthetic board minutes','Private report','["Decision"]','["Action"]','https://example.invalid/source',true,h) THEN RAISE EXCEPTION 'Duplicate import'; END IF;
 SELECT meeting_id INTO mid FROM public.board_minutes_versions WHERE id=v;
 path:=mid::text||'/'||h||'.pdf';
 BEGIN PERFORM public.board_minutes_adopt(v,true); RAISE EXCEPTION 'Adopt without original allowed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Adopt without original allowed' THEN RAISE; END IF; END;
 BEGIN INSERT INTO public.board_minutes_versions(meeting_id,version,meeting_date,title,content_hash,created_by) VALUES(mid,2,'2026-11-06','Forged','x',auth.uid()); RAISE EXCEPTION 'Direct write allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 INSERT INTO storage.objects(bucket_id,name,metadata) VALUES('board-minutes',path,'{"size":12}');
 f:=public.board_minutes_attach(v,path,'Original name.pdf',h,12);
 IF f IS DISTINCT FROM public.board_minutes_attach(v,path,'Original name.pdf',h,12) THEN RAISE EXCEPTION 'Duplicate file'; END IF;
 PERFORM public.board_minutes_adopt(v,true);
 IF NOT EXISTS(SELECT 1 FROM public.board_minutes_adoptions WHERE version_id=v AND adopted_by=auth.uid()) THEN RAISE EXCEPTION 'Adoption actor'; END IF;
 BEGIN PERFORM public.board_minutes_attach(v,path,'Other name.pdf',h,12); RAISE EXCEPTION 'Adopted attachment mutation allowed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Adopted attachment mutation allowed' THEN RAISE; END IF; END;
 v2:=public.board_minutes_save_revision(mid,v,'topical','synthetic-original','2026-11-06','Synthetic board minutes','Private report revised','["Decision"]','["Action"]','https://example.invalid/source',true,NULL);
 SELECT count(*) INTO n FROM public.board_minutes_files WHERE version_id=v2; IF n<>1 THEN RAISE EXCEPTION 'Original not inherited'; END IF;
 v3:=public.board_minutes_save_revision(NULL,NULL,'topical','synthetic-original','2026-11-06','Synthetic board minutes','Private report revised','["Decision"]','["Action"]','https://example.invalid/source',true,repeat('b',64));
 IF v3=v2 THEN RAISE EXCEPTION 'Changed original hash lost'; END IF;
 SELECT count(*) INTO n FROM public.board_minutes_versions WHERE meeting_id=mid; IF n<>3 THEN RAISE EXCEPTION 'Version history lost'; END IF;
 BEGIN PERFORM public.board_minutes_save_revision(mid,v,'topical','synthetic-original','2026-11-06','Stale edit','Different','[]','[]',NULL,true,NULL); RAISE EXCEPTION 'Stale overwrite'; EXCEPTION WHEN serialization_failure THEN NULL; END;
 BEGIN UPDATE storage.objects SET name='changed' WHERE bucket_id='board-minutes'; RAISE EXCEPTION 'Storage overwrite allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true); SET LOCAL ROLE authenticated;
 SELECT count(*) INTO n FROM public.board_minutes_versions; IF n<>3 THEN RAISE EXCEPTION 'Board cannot read'; END IF;
 SELECT count(*) INTO n FROM storage.objects WHERE bucket_id='board-minutes'; IF n<>1 THEN RAISE EXCEPTION 'Board cannot download'; END IF;
 BEGIN PERFORM public.board_minutes_adopt(v3,true); RAISE EXCEPTION 'Board can adopt'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.board_minutes_save_revision(mid,v3,'topical','synthetic-original','2026-11-06','Forbidden','x','[]','[]',NULL,true,NULL); RAISE EXCEPTION 'Board can manage'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 FOREACH actor IN ARRAY ARRAY['00000000-0000-0000-0000-000000000003'::uuid,'00000000-0000-0000-0000-000000000004'::uuid,'00000000-0000-0000-0000-000000000005'::uuid] LOOP
 PERFORM set_config('request.jwt.claim.sub',actor::text,true); SET LOCAL ROLE authenticated;
 SELECT count(*) INTO n FROM public.board_minutes_meetings; IF n<>0 THEN RAISE EXCEPTION 'Metadata leak'; END IF;
 SELECT count(*) INTO n FROM public.board_minutes_versions WHERE report ILIKE '%private%'; IF n<>0 THEN RAISE EXCEPTION 'Search/report leak'; END IF;
 SELECT count(*) INTO n FROM public.board_minutes_files; IF n<>0 THEN RAISE EXCEPTION 'Attachment metadata leak'; END IF;
 SELECT count(*) INTO n FROM public.board_minutes_adoptions; IF n<>0 THEN RAISE EXCEPTION 'Adoption leak'; END IF;
 SELECT count(*) INTO n FROM storage.objects WHERE bucket_id='board-minutes'; IF n<>0 THEN RAISE EXCEPTION 'Download leak'; END IF;
 BEGIN PERFORM public.board_minutes_save_revision(NULL,NULL,'upload','forbidden','2026-11-06','Forbidden','x','[]','[]',NULL,true,NULL); RAISE EXCEPTION 'Member write allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE; END LOOP;
 PERFORM set_config('request.jwt.claim.sub','',true); SET LOCAL ROLE anon;
 BEGIN PERFORM * FROM public.board_minutes_versions; RAISE EXCEPTION 'Anon report access'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.board_minutes_save_revision(NULL,NULL,'upload','forbidden','2026-11-06','Forbidden','x','[]','[]',NULL,true,NULL); RAISE EXCEPTION 'Anon write allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 SELECT count(*) INTO n FROM storage.objects WHERE bucket_id='board-minutes'; IF n<>0 THEN RAISE EXCEPTION 'Anon download leak'; END IF;
 RESET ROLE;
 RAISE NOTICE 'PASS: admin read/write/adopt; board read/download only; member/extern/inhuur/anon denied; original hashes/versions/dedup/stale edit protected';
END $$;
ROLLBACK;
SELECT (SELECT count(*) FROM public.board_minutes_meetings) meetings_after_rollback,(SELECT count(*) FROM storage.objects) objects_after_rollback;